INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM216LIWK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = 2(3)^x$. Which of the following best describes the behavior of $g(x)$ as $x$ increases?', NULL, $lyceon_json$[{"key":"A","text":"$g(x)$ increases at a constant rate."},{"key":"B","text":"$g(x)$ increases at an increasing rate."},{"key":"C","text":"$g(x)$ increases at a decreasing rate."},{"key":"D","text":"$g(x)$ decreases at an increasing rate."}]$lyceon_json$::jsonb, 'B', NULL, E'The function $g(x) = 2(3)^x$ is an exponential function with base $3 > 1$. As $x$ increases, $g(x)$ grows by a constant factor of $3$ per unit increase in $x$, which means the rate of increase itself grows — the function increases at an increasing rate. The distractor claiming a constant rate confuses exponential growth with linear growth. The distractor claiming an increasing rate that decreases confuses exponential growth with logarithmic growth. The distractor claiming the function decreases applies only when the base is between $0$ and $1$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21B6ZQY', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $f(x) = -3x + 24$ models the number of gallons of water remaining in a tank after $x$ minutes of draining. After how many minutes will the tank contain half of its initial amount of water?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'A', NULL, E'The initial amount is $f(0) = 24$ gallons, so half the initial amount is $12$ gallons. Setting $f(x) = 12$ gives $-3x + 24 = 12$, so $-3x = -12$ and $x = 4$. The value $8$ is when the tank is completely empty ($f(8) = 0$), not half full. The value $12$ confuses the target water level in gallons with the number of minutes. The value $6$ results from an arithmetic error when solving the equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22EQ2U5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A scatterplot of data for $20$ cities shows the relationship between average annual temperature, in degrees Fahrenheit, and average annual rainfall, in inches. The equation of the line of best fit is $y = 0.84x - 12.6$, where $x$ is the average temperature and $y$ is the predicted rainfall. The correlation coefficient is $r = 0.91$. Which of the following is the best interpretation of the slope $0.84$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each increase of $1$ degree Fahrenheit in average temperature, the predicted average rainfall increases by $0.84$ inches."},{"key":"B","text":"For each increase of $1$ inch in average rainfall, the predicted average temperature increases by $0.84$ degrees Fahrenheit."},{"key":"C","text":"For each increase of $0.84$ degrees Fahrenheit in average temperature, the predicted average rainfall increases by $1$ inch."},{"key":"D","text":"The average rainfall is $84\\%$ of the average temperature across all cities."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a linear model represents the predicted change in the dependent variable ($y$, rainfall) for each one-unit increase in the independent variable ($x$, temperature). Therefore $0.84$ means that for each increase of $1$ degree Fahrenheit in average temperature, the predicted average rainfall increases by $0.84$ inches. The interpretation that reverses the variables confuses the roles of $x$ and $y$. The interpretation that $0.84$ degrees yields $1$ inch of rainfall inverts the slope relationship ($\\frac{1}{0.84}$ would give approximately $1.19$ degrees per inch, but that describes the inverse model). The claim that rainfall is $84\\%$ of temperature conflates the slope with a percentage ratio, ignoring the intercept and the units.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22X01G2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $JKL$, the right angle is at vertex $K$. If $\\sin(J) = \\frac{3}{5}$ and the hypotenuse $JL = 20$, what is the value of $JK + KL$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '28', ARRAY['28'], E'Since $\\sin(J) = \\frac{3}{5}$ and the hypotenuse $JL = 20$, the side opposite angle $J$ is $KL = \\frac{3}{5} \\times 20 = 12$. The side adjacent to angle $J$ is $JK = \\sqrt{20^2 - 12^2} = \\sqrt{400 - 144} = \\sqrt{256} = 16$. Therefore $JK + KL = 16 + 12 = 28$. A common error is confusing which leg is opposite and which is adjacent to angle $J$, yielding $JK = 12$ and $KL = 16$ but arriving at the same sum. A more consequential error is misapplying the ratio by computing $KL = \\frac{3}{5} \\times 20 = 12$ correctly but then computing $JK = 20 - 12 = 8$ instead of using the Pythagorean theorem, giving an incorrect sum of $20$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM234G4CL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school district found that students who participated in an after-school tutoring program scored higher on the state math exam than students who did not participate. Participation was voluntary. Which of the following is a valid conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The tutoring program caused the higher scores."},{"key":"B","text":"Students who chose to participate may have been more motivated, so the difference could be due to a confounding variable."},{"key":"C","text":"The tutoring program had no effect because this was not an experiment."},{"key":"D","text":"A larger sample size would confirm that the tutoring program caused the improvement."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participation was voluntary, this is an observational study. Students who chose to enroll may differ systematically from those who did not — for instance, in motivation or prior achievement — creating a confounding variable. The claim that the program caused higher scores is not supported because causation cannot be established without random assignment. The claim that the program had no effect goes too far in the other direction; the study simply cannot establish causation, which does not mean there is no effect. The claim that a larger sample would confirm causation is incorrect because sample size does not eliminate confounding in an observational study.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23DPHAM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher records the number of hours studied and the test score for each of $12$ students and creates a scatterplot. The line of best fit is $y = 5.2x + 42$, where $x$ is the number of hours studied and $y$ is the predicted test score. One student studied for $6$ hours and earned a score of $78$. What is the residual for this student''s data point?', NULL, $lyceon_json$[{"key":"A","text":"$-35.2$"},{"key":"B","text":"$-4.8$"},{"key":"C","text":"$4.8$"},{"key":"D","text":"$73.2$"}]$lyceon_json$::jsonb, 'C', NULL, E'The predicted score is $5.2(6) + 42 = 31.2 + 42 = 73.2$. The residual is the actual value minus the predicted value: $78 - 73.2 = 4.8$. The result $-4.8$ comes from reversing the subtraction order (predicted minus actual), which is a sign error. The result $-35.2$ comes from computing $42 - 78 + 5.2 = -35.2$ or another setup error. The result $73.2$ is the predicted value itself, not the residual.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM245C0WV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, point $D$ lies on side $\\overline{BC}$ such that $\\overline{AD}$ bisects angle $A$. If $AB = 15$, $AC = 9$, and $BC = 16$, what is the length of $BD$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'By the angle bisector theorem, the bisector from vertex $A$ divides the opposite side in the ratio of the adjacent sides: $\\frac{BD}{DC} = \\frac{AB}{AC} = \\frac{15}{9} = \\frac{5}{3}$. Since $BD + DC = 16$, let $BD = 5k$ and $DC = 3k$. Then $5k + 3k = 16$, so $8k = 16$ and $k = 2$. Therefore $BD = 5(2) = 10$. A common error is to invert the ratio, setting $\\frac{BD}{DC} = \\frac{AC}{AB} = \\frac{9}{15}$, which gives $BD = 6$. Another error is to assume $D$ is the midpoint of $BC$, yielding $BD = 8$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24H9GGU', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'Solve for $x$: $$3x = 18$$', NULL, $lyceon_json$[{"key":"A","text":"$-16$"},{"key":"B","text":"$6$"},{"key":"C","text":"$15$"},{"key":"D","text":"$54$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $6$. Dividing both sides of $3x = 18$ by $3$ gives $x = 6$. The value $-16$ results from subtracting $2$ after incorrectly computing $18 - 3 = 15$ and then applying a sign error. The value $15$ comes from subtracting $3$ from $18$ instead of dividing. The value $54$ comes from multiplying $18$ by $3$ instead of dividing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24JD4NK', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 9}{x^2 + 5x + 6}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 3}{x + 2}$"},{"key":"B","text":"$\\frac{x - 3}{x + 2}$"},{"key":"C","text":"$\\frac{x - 3}{x + 3}$"},{"key":"D","text":"$\\frac{x - 9}{x + 6}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator as a difference of squares: $x^2 - 9 = (x - 3)(x + 3)$. Factor the denominator: $x^2 + 5x + 6 = (x + 2)(x + 3)$. Cancel the common factor $(x + 3)$ to get $\\frac{x - 3}{x + 2}$. The distractor $\\frac{x + 3}{x + 2}$ results from a sign error, canceling $(x - 3)$ instead of $(x + 3)$. The distractor $\\frac{x - 3}{x + 3}$ arises from canceling the wrong factor in the denominator. The distractor $\\frac{x - 9}{x + 6}$ comes from incorrectly removing the $x^2$ terms rather than factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24Z8KU7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A ramp rises at an angle of $12^\\circ$ from the horizontal ground. If the ramp covers a horizontal distance of $20$ feet, which expression gives the length of the ramp, in feet?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{20}{\\cos(12^\\circ)}$"},{"key":"B","text":"$20\\cos(12^\\circ)$"},{"key":"C","text":"$\\frac{20}{\\sin(12^\\circ)}$"},{"key":"D","text":"$20\\tan(12^\\circ)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The horizontal distance is the side adjacent to the $12^\\circ$ angle, and the ramp is the hypotenuse. Using $\\cos(12^\\circ) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{20}{\\text{ramp length}}$, solving gives ramp length $= \\frac{20}{\\cos(12^\\circ)}$. The expression $20\\cos(12^\\circ)$ incorrectly multiplies rather than divides, producing a value smaller than the horizontal distance. The expression $\\frac{20}{\\sin(12^\\circ)}$ confuses the adjacent side with the opposite side. The expression $20\\tan(12^\\circ)$ computes the vertical rise of the ramp, not its length.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28M2W7A', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $14$ centimeters. What is the circumference of the circle, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$7\\pi$"},{"key":"B","text":"$14\\pi$"},{"key":"C","text":"$28\\pi$"},{"key":"D","text":"$49\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Since $d = 14$, the circumference is $14\\pi$ centimeters. The value $7\\pi$ results from using the radius in the diameter formula, computing $\\pi r$ instead of $\\pi d$. The value $28\\pi$ comes from doubling the diameter, as if the formula were $2\\pi d$. The value $49\\pi$ results from computing $\\pi r^2$ (the area formula with $r = 7$) instead of the circumference formula.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM297LIMV', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'In the system of equations below, $k$ is a constant. If the system has no solution, what is the value of $k$?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29G8UPF', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $k$ passes through the point $(2, 7)$ and is perpendicular to the line $3x - 6y = 18$. What is the $y$-intercept of line $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-11$"},{"key":"B","text":"$3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'D', NULL, E'Rewriting $3x - 6y = 18$ in slope-intercept form gives $y = \\frac{1}{2}x - 3$, so the slope is $\\frac{1}{2}$. A line perpendicular to this has slope $-2$ (the negative reciprocal). Using point-slope form with $(2, 7)$: $y - 7 = -2(x - 2)$, which simplifies to $y = -2x + 11$. The $y$-intercept is $11$. The value $3$ results from using the reciprocal slope $2$ without negating it, giving $y = 2x + 3$. The value $-11$ results from a sign error in the final calculation. The value $7$ is the $y$-coordinate of the given point, not the $y$-intercept of the line.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29HPINA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills $240$ bottles in $4$ hours. At this constant rate, how many bottles does the machine fill in $7$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$360$"},{"key":"B","text":"$420$"},{"key":"C","text":"$480$"},{"key":"D","text":"$960$"}]$lyceon_json$::jsonb, 'B', NULL, E'The machine fills $\\frac{240}{4} = 60$ bottles per hour. In $7$ hours it fills $60 \\times 7 = 420$ bottles. The result $360$ comes from an arithmetic slip such as multiplying $60 \\times 6$. The result $480$ comes from incorrectly doubling the original $240$. The result $960$ comes from multiplying $240 \\times 4$ instead of dividing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29RNNK4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A data set consists of $10$ values. The mean of the data set is $14$ and the mean of $9$ of the values is $12$. What is the value of the remaining data point?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '32', ARRAY['32'], E'The sum of all $10$ values is $10 \\times 14 = 140$. The sum of the $9$ known values is $9 \\times 12 = 108$. Therefore, the remaining value is $140 - 108 = 32$. A common error is subtracting the means directly to get $14 - 12 = 2$, which confuses individual values with averages. Another error is computing $10 \\times 12 = 120$ and then $140 - 120 = 20$, which uses the wrong count with the mean of $9$ values.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29Y1LJ0', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(1, 5)$ and $(3, 11)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'The slope of the line is $\\frac{11 - 5}{3 - 1} = \\frac{6}{2} = 3$. Using point-slope form with the point $(1, 5)$: $y - 5 = 3(x - 1)$, which simplifies to $y = 3x + 2$. The $y$-intercept is $2$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29ZL36E', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 3x^2 - 7$. What is the value of $f(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$68$"},{"key":"C","text":"$38$"},{"key":"D","text":"$218$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substitute $x = 5$: $f(5) = 3(5)^2 - 7 = 3(25) - 7 = 75 - 7 = 68$. The distractor $23$ results from computing $3(5) + 2(5) - 7 = 23$, treating $3x^2$ as $3x + 2x$. The distractor $38$ comes from computing $5^2 - 7 = 18$ and then doubling to get $38$, misapplying the coefficient. The distractor $218$ arises from computing $3(5^3) - 7 = 375 - 7 = 368$, then misreading — or from $3(75) - 7 = 218$, an arithmetic error in which $3 \\times 75$ is calculated as $225$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AIWJ5N', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-intercept of the line $2x + 4y = 12$?', NULL, $lyceon_json$[{"key":"A","text":"$(3, 0)$"},{"key":"B","text":"$(6, 0)$"},{"key":"C","text":"$(0, 3)$"},{"key":"D","text":"$(0, 6)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $x$-intercept occurs where $y = 0$. Substituting into $2x + 4(0) = 12$ gives $2x = 12$, so $x = 6$, and the $x$-intercept is $(6, 0)$. The point $(3, 0)$ results from dividing $12$ by $4$ instead of by $2$. The point $(0, 3)$ is the $y$-intercept, not the $x$-intercept. The point $(0, 6)$ incorrectly places the $x$-value of $6$ in the $y$-coordinate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BDV7YU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, the length of one leg is $6$ and the length of the hypotenuse is $10$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\sqrt{136}$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem $a^2 + b^2 = c^2$ with $c = 10$ and $a = 6$: $b^2 = 100 - 36 = 64$, so $b = 8$. The value $4$ results from a computational error in the subtraction step. The value $\\sqrt{136}$ comes from adding the squares instead of subtracting ($6^2 + 10^2 = 136$), treating the hypotenuse as a leg. The value $16$ comes from computing $b^2 = 64$ but doubling instead of taking the square root.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BH2MBW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $5$ red marbles, $3$ blue marbles, and $2$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{5}$"},{"key":"B","text":"$\\frac{3}{10}$"},{"key":"C","text":"$\\frac{1}{2}$"},{"key":"D","text":"$\\frac{3}{5}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is $5 + 3 + 2 = 10$. There are $3$ blue marbles, so the probability of selecting a blue marble is $\\frac{3}{10}$. The distractor $\\frac{1}{5}$ results from incorrectly using $2$ (the count of green marbles) in the numerator instead of $3$. The distractor $\\frac{1}{2}$ reflects a misconception that there are only two possible outcomes. The distractor $\\frac{3}{5}$ results from dividing the number of blue marbles by the number of red marbles rather than by the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BOAUUE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $h$ is defined by $h(x) = -2(x - 3)^2 + 18$. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'The function $h(x) = -2(x - 3)^2 + 18$ is in vertex form $a(x - h)^2 + k$ with $a = -2$, vertex at $(3, 18)$. Since $a < 0$, the parabola opens downward and the vertex represents the maximum point. The maximum value is $18$. A common error is expanding the expression and attempting to use the quadratic formula, which finds the zeros rather than the vertex. Another error is misidentifying the vertex as $(3, -18)$ due to a sign mistake with the constant term.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BZWC4U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A medical test for a certain condition has a $95\\%$ true positive rate and a $3\\%$ false positive rate. In a population where $2\\%$ of people have the condition, a person is selected at random and tests positive. What is the probability, to the nearest hundredth, that this person actually has the condition?', NULL, $lyceon_json$[{"key":"A","text":"$0.39$"},{"key":"B","text":"$0.50$"},{"key":"C","text":"$0.65$"},{"key":"D","text":"$0.95$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using Bayes'' theorem, the probability of having the condition given a positive test is $P(\\text{condition} \\mid \\text{positive}) = \\frac{P(\\text{positive} \\mid \\text{condition}) \\cdot P(\\text{condition})}{P(\\text{positive})}$. The numerator is $0.95 \\times 0.02 = 0.019$. The denominator is $P(\\text{positive}) = (0.95)(0.02) + (0.03)(0.98) = 0.019 + 0.0294 = 0.0484$. Therefore $P(\\text{condition} \\mid \\text{positive}) = \\frac{0.019}{0.0484} \\approx 0.39$. The distractor $0.50$ reflects a guess that a positive test means an even chance. The distractor $0.65$ results from incorrectly computing $P(\\text{positive})$ by omitting the false positive contribution from the non-condition group. The distractor $0.95$ confuses the true positive rate with the posterior probability, ignoring the low base rate of the condition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C43V1A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to test whether a new fertilizer increases tomato yield. They randomly assigned $40$ identical tomato plots to two groups: $20$ plots received the new fertilizer, and $20$ plots received a standard fertilizer. All other growing conditions were kept the same. At the end of the season, the group using the new fertilizer had a statistically significantly higher average yield. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer causes higher tomato yield compared to the standard fertilizer."},{"key":"B","text":"The new fertilizer is associated with higher yield, but the study cannot establish causation."},{"key":"C","text":"The result is likely due to differences in soil quality between the two groups."},{"key":"D","text":"The sample size is too small to draw any conclusion."}]$lyceon_json$::jsonb, 'A', NULL, E'This is a randomized controlled experiment: plots were randomly assigned to treatment and control groups, and all other conditions were held constant. Because of random assignment and controlled conditions, a statistically significant result supports a causal conclusion. The distractor claiming the study cannot establish causation incorrectly applies the limitation of observational studies to a properly designed experiment. The distractor about soil quality differences is unlikely because random assignment distributes such variations evenly across groups. The distractor about sample size is unfounded because the study already achieved statistical significance, indicating the sample was sufficient to detect the effect.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CDTWXS', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $g$ satisfies $g(-2) = 13$ and $g(4) = -5$. If $g(a) = 0$, what is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/3', ARRAY['7/3', '2.333'], E'The slope of $g$ is $\\frac{-5 - 13}{4 - (-2)} = \\frac{-18}{6} = -3$. Using the point $(-2, 13)$ in point-slope form: $g(x) = -3(x + 2) + 13 = -3x - 6 + 13 = -3x + 7$. Setting $g(a) = 0$ gives $-3a + 7 = 0$, so $a = \\frac{7}{3}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D2BU5K', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A store requires that customers spend more than $\\$25$ to qualify for free shipping. Which inequality represents the amount $x$, in dollars, a customer must spend to qualify?', NULL, $lyceon_json$[{"key":"A","text":"$x > 25$"},{"key":"B","text":"$x < 25$"},{"key":"C","text":"$x \\geq 25$"},{"key":"D","text":"$x \\leq 25$"}]$lyceon_json$::jsonb, 'A', NULL, E'The store requires spending more than $\\$25$, which translates to the strict inequality $x > 25$. The inequality $x < 25$ reverses the direction, representing amounts less than $\\$25$. The inequality $x \\geq 25$ incorrectly includes exactly $\\$25$, but the requirement is strictly more than $\\$25$. The inequality $x \\leq 25$ both reverses the direction and includes $\\$25$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FHV5D8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylindrical water tank has a radius of $3$ feet and a height of $8$ feet. What is the volume of the tank, in cubic feet?', NULL, $lyceon_json$[{"key":"A","text":"$24\\pi$"},{"key":"B","text":"$72\\pi$"},{"key":"C","text":"$48\\pi$"},{"key":"D","text":"$144\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of a cylinder is $V = \\pi r^2 h$. With $r = 3$ and $h = 8$: $V = \\pi(3)^2(8) = 72\\pi$ cubic feet. The value $24\\pi$ comes from omitting the squaring of the radius, computing $\\pi(3)(8) = 24\\pi$. The value $48\\pi$ results from using the diameter ($6$) linearly: $\\pi(6)(8) = 48\\pi$. The value $144\\pi$ comes from using the diameter squared without the $\\frac{1}{4}$ correction: $\\pi(6)^2(8) \\div 2 = 144\\pi$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FVJ0C7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town increased from $8{,}000$ to $9{,}200$ over a one-year period. What was the percent increase in the town''s population?', NULL, $lyceon_json$[{"key":"A","text":"$12\\%$"},{"key":"B","text":"$13\\%$"},{"key":"C","text":"$15\\%$"},{"key":"D","text":"$86.9\\%$"}]$lyceon_json$::jsonb, 'C', NULL, E'The increase is $9{,}200 - 8{,}000 = 1{,}200$. The percent increase is $\\frac{1{,}200}{8{,}000} \\times 100 = 15\\%$. The result $12\\%$ comes from an arithmetic slip in the division. The result $13\\%$ comes from dividing the increase by the new population ($\\frac{1{,}200}{9{,}200}$) instead of the original. The result $86.9\\%$ comes from computing $\\frac{8{,}000}{9{,}200} \\times 100$, which gives the ratio of old to new rather than the percent change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
