INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G6WTJX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 6x + 10y + 18 = 0$. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$16$"},{"key":"C","text":"$\\sqrt{7}$"},{"key":"D","text":"$\\sqrt{52}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Completing the square: for $x$, $x^2 - 6x = (x - 3)^2 - 9$; for $y$, $y^2 + 10y = (y + 5)^2 - 25$. Substituting: $(x - 3)^2 - 9 + (y + 5)^2 - 25 + 18 = 0$, which gives $(x - 3)^2 + (y + 5)^2 = 16$. Since the standard form is $(x - h)^2 + (y - k)^2 = r^2$, we have $r^2 = 16$ and $r = 4$. The value $16$ is $r^2$ itself, from failing to take the square root. The value $\\sqrt{7}$ comes from an arithmetic error when combining the constants $-9$, $-25$, and $18$. The value $\\sqrt{52}$ results from a sign error, adding instead of subtracting the completed-square constants.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H3LRJZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A technology company conducted a study to determine whether using standing desks reduces employee sick days. They offered standing desks to all employees at one office location and kept traditional desks at a second office location. After one year, employees at the standing-desk office averaged $3.2$ sick days compared to $5.1$ sick days at the traditional-desk office. The company concluded that standing desks reduce sick days. Which of the following is the most significant flaw in the study design?', NULL, $lyceon_json$[{"key":"A","text":"The study did not last long enough to detect a difference."},{"key":"B","text":"The two office locations may differ in ways unrelated to desk type, making it impossible to attribute the difference solely to the desks."},{"key":"C","text":"The company should have used a larger sample of offices to increase statistical power."},{"key":"D","text":"Standing desks could not plausibly affect the number of sick days an employee takes."}]$lyceon_json$::jsonb, 'B', NULL, E'The critical flaw is confounding: by assigning the treatment to an entire office rather than randomly assigning individual employees, the study confounds desk type with all other differences between the two offices — such as regional climate, workplace culture, employee demographics, or management practices. Any of these could explain the difference in sick days. The distractor about study duration is incorrect because a full year is a reasonable observation period and a difference was in fact observed. The distractor about needing more offices, while potentially useful for generalizability, does not address the core confounding problem within this study. The distractor denying any plausible mechanism is an unsupported assertion and does not identify a design flaw.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HYSZKH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures $(3x + 14)^\\circ$, and its co-interior angle (same-side interior angle) measures $(5x - 10)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$22$"},{"key":"B","text":"$3$"},{"key":"C","text":"$12$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'A', NULL, E'Co-interior angles formed by a transversal cutting parallel lines are supplementary, so they sum to $180^\\circ$. Setting up the equation: $(3x + 14) + (5x - 10) = 180$, which simplifies to $8x + 4 = 180$, giving $8x = 176$ and $x = 22$. The value $3$ results from misreading and solving a different simplified equation. The value $12$ comes from treating the angles as equal (alternate interior angles) rather than supplementary: $3x + 14 = 5x - 10$ yields $x = 12$. The value $24$ arises from an arithmetic slip such as computing $176 \\div 8$ incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JDOS58', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47^\\circ$ and the measure of angle $Q$ is $65^\\circ$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$68$"},{"key":"B","text":"$78$"},{"key":"C","text":"$112$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. Therefore, angle $R = 180 - 47 - 65 = 68$ degrees. The value $78$ results from an arithmetic slip in the subtraction. The value $112$ comes from adding $47 + 65 = 112$ and reporting the sum rather than subtracting it from $180$. The value $22$ results from an incorrect setup, such as computing $65 - 47 = 18$ and adjusting arbitrarily.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JERT1E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A map uses a scale of $1$ centimeter to $15$ kilometers. Two cities are $7.4$ centimeters apart on the map. What is the actual distance, in kilometers, between the two cities?', NULL, $lyceon_json$[{"key":"A","text":"$96$"},{"key":"B","text":"$111$"},{"key":"C","text":"$115$"},{"key":"D","text":"$120$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the scale, the actual distance is $7.4 \\times 15 = 111$ kilometers. The result $96$ comes from an arithmetic slip such as computing $7.4 \\times 13$. The result $115$ comes from rounding $7.4$ to $7.5$ and then multiplying, or another arithmetic error. The result $120$ comes from rounding $7.4$ up to $8$ and multiplying by $15$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K63DAP', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'$$5(x - 3) + 2 = 4x + 7$$ What is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20', ARRAY['20'], E'Distributing $5$ across $(x - 3)$ gives $5x - 15$, so the equation becomes $5x - 15 + 2 = 4x + 7$, which simplifies to $5x - 13 = 4x + 7$. Subtracting $4x$ from both sides gives $x - 13 = 7$. Adding $13$ to both sides yields $x = 20$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KN647T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A store sells a jacket for $\\$80$. During a sale, the price is reduced by $25\\%$. What is the sale price of the jacket, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$\\$20$"},{"key":"B","text":"$\\$55$"},{"key":"C","text":"$\\$60$"},{"key":"D","text":"$\\$100$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $25\\%$ reduction means the discount is $0.25 \\times 80 = \\$20$, so the sale price is $80 - 20 = \\$60$. The result $\\$20$ is just the discount amount, not the sale price. The result $\\$55$ comes from an arithmetic error such as subtracting $25$ from $80$. The result $\\$100$ comes from adding the discount instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KU3ZEJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $600$ adults in a state and finds that $35\\%$ support a new tax policy, with a margin of error of $\\pm 3$ percentage points at the $95\\%$ confidence level. A second researcher surveys a random sample of $150$ adults from the same state on the same question and reports a margin of error of $\\pm 6$ percentage points. Which of the following best explains why the second survey has a larger margin of error?', NULL, $lyceon_json$[{"key":"A","text":"The second researcher used a biased sampling method."},{"key":"B","text":"The second survey had a smaller sample size, which increases sampling variability."},{"key":"C","text":"The second researcher measured a different population proportion."},{"key":"D","text":"The margin of error increases when the true population proportion is farther from $50\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error for a proportion is inversely related to the square root of the sample size. A smaller sample of $150$ adults produces more sampling variability than a sample of $600$, resulting in a wider confidence interval and larger margin of error. The distractor about biased sampling is unsupported; both surveys used random samples. The distractor about measuring a different proportion is incorrect since both surveys address the same question in the same state. The distractor about distance from $50\\%$ describes a real but secondary effect that does not explain the difference here, since the dominant factor is the fourfold reduction in sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MBDHMQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages of participants in a workshop are $22, 25, 27, 28, 30, 31, 35, 62$. Which of the following best describes how removing the value $62$ from the data set would affect the mean and median?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median would decrease."},{"key":"B","text":"The mean would decrease, but the median would stay the same."},{"key":"C","text":"The median would decrease, but the mean would stay the same."},{"key":"D","text":"Both the mean and the median would stay the same."}]$lyceon_json$::jsonb, 'A', NULL, E'With all $8$ values, the mean is $\\frac{22+25+27+28+30+31+35+62}{8} = \\frac{260}{8} = 32.5$ and the median is $\\frac{28+30}{2} = 29$. Removing $62$ gives $7$ values with mean $\\frac{198}{7} \\approx 28.3$ and median $28$. Both the mean and the median decrease. The claim that the median stays the same overlooks the shift: with an even count the median is the average of the two middle values, but with an odd count it is the single middle value, which changes here. The claim that the mean stays the same ignores that removing a value well above the mean pulls the mean down.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q1LI6X', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A solid cone has a base radius of $6$ centimeters and a height of $9$ centimeters. A plane parallel to the base cuts the cone at a height of $6$ centimeters from the base, removing a smaller cone from the top. What is the volume of the frustum (the remaining solid) in cubic centimeters, divided by $\\pi$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '104', ARRAY['104'], E'The original cone has radius $6$ and height $9$. Its volume is $\\frac{1}{3}\\pi(6)^2(9) = \\frac{1}{3}(36)(9)\\pi = 108\\pi$ cubic centimeters. The cut is at $6$ cm from the base, so the small cone at the top has height $9 - 6 = 3$ cm. By similar triangles, its radius is $\\frac{3}{9} \\times 6 = 2$ cm. The small cone''s volume is $\\frac{1}{3}\\pi(2)^2(3) = \\frac{1}{3}(4)(3)\\pi = 4\\pi$ cubic centimeters. The frustum volume is $108\\pi - 4\\pi = 104\\pi$, so the volume divided by $\\pi$ is $104$. A common error is computing the small cone''s radius using the distance from the base ($6$) rather than from the apex ($3$), giving a radius of $4$ and a volume of $16\\pi$, which leads to $92$ instead of $104$. Another error is forgetting the $\\frac{1}{3}$ factor for one or both cones.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QRTRLY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $2x^2 - 8x + 6 = 0$, what is the positive difference between the two solutions?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Factor out $2$: $2(x^2 - 4x + 3) = 0$, so $x^2 - 4x + 3 = 0$. Factor the quadratic: $(x - 1)(x - 3) = 0$, giving $x = 1$ and $x = 3$. The positive difference is $|3 - 1| = 2$. A common error is forgetting to factor out the leading coefficient first and obtaining incorrect roots. Another error is finding the roots correctly but computing $3 + 1 = 4$ instead of the difference.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QUAPAW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $12$ meters and a width of $7$ meters. What is the area of the garden, in square meters?', NULL, $lyceon_json$[{"key":"A","text":"$38$"},{"key":"B","text":"$84$"},{"key":"C","text":"$19$"},{"key":"D","text":"$72$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a rectangle is length times width: $A = 12 \\times 7 = 84$ square meters. The value $38$ is the perimeter ($2(12 + 7) = 38$), resulting from confusing area with perimeter. The value $19$ comes from adding the dimensions ($12 + 7 = 19$) instead of multiplying. The value $72$ results from an arithmetic slip such as computing $12 \\times 6$ instead of $12 \\times 7$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QXS7BR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 3x + 10$. According to this model, what is the predicted value of $y$ when $x = 5$?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$18$"},{"key":"C","text":"$25$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 5$ into $y = 3x + 10$ gives $y = 3(5) + 10 = 15 + 10 = 25$. The result $15$ comes from computing $3 \\times 5$ but neglecting to add the $y$-intercept of $10$. The result $18$ comes from an arithmetic slip such as computing $3 + 5 + 10$. The result $50$ comes from multiplying $5 \\times 10$ rather than following the equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RAAUKW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'grid_in', E'A polling organization surveys a random sample of $n$ likely voters and wants the margin of error for the estimated proportion to be at most $4$ percentage points at the $95\\%$ confidence level. Using the conservative estimate $\\hat{p} = 0.5$ and the formula $\\text{ME} = 1.96\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}}$, what is the minimum whole number value of $n$ that satisfies this requirement?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '601', ARRAY['601'], E'Setting up the inequality $1.96\\sqrt{\\frac{0.5 \\times 0.5}{n}} \\leq 0.04$ and solving: $\\sqrt{\\frac{0.25}{n}} \\leq \\frac{0.04}{1.96}$. Squaring both sides gives $\\frac{0.25}{n} \\leq \\left(\\frac{0.04}{1.96}\\right)^2 = \\frac{0.0016}{3.8416} \\approx 0.000416493$. Therefore $n \\geq \\frac{0.25}{0.000416493} \\approx 600.23$. Since $n$ must be a whole number and must satisfy the inequality, the minimum value is $601$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S2OYSE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 + 3x - 28 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 4$ and $x = -7$"},{"key":"B","text":"$x = -4$ and $x = 7$"},{"key":"C","text":"$x = 14$ and $x = -2$"},{"key":"D","text":"$x = 2$ and $x = -14$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the quadratic: $x^2 + 3x - 28 = (x + 7)(x - 4) = 0$, so $x = -7$ or $x = 4$. The distractor $x = -4$ and $x = 7$ results from a sign error — reversing the signs when reading roots from the factored form $(x + 7)(x - 4)$. The distractor $x = 14$ and $x = -2$ uses a factor pair of $-28$ whose product is correct but whose sum is $12$, not $3$. The distractor $x = 2$ and $x = -14$ similarly uses an incorrect factor pair with the right product but wrong sum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S90RG2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $400$ voters in a city found that $52\\%$ support a proposed parks initiative. The margin of error for the survey is $4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $52\\%$ of all voters in the city support the initiative."},{"key":"B","text":"Between $48\\%$ and $56\\%$ of voters in the sample support the initiative."},{"key":"C","text":"It is plausible that between $48\\%$ and $56\\%$ of all voters in the city support the initiative."},{"key":"D","text":"The survey is unreliable because the margin of error is too large."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of $4$ percentage points means the plausible range for the true population proportion is $52\\% \\pm 4\\%$, or between $48\\%$ and $56\\%$. This interval applies to the population parameter, not the sample statistic. The distractor stating exactly $52\\%$ ignores sampling variability entirely. The distractor applying the interval to the sample confuses the sample statistic (which is known) with the population parameter (which is estimated). The distractor claiming the survey is unreliable has no basis, since a $4$-point margin of error is typical for a sample of this size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SSX386', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A laptop originally priced at $\\$1{,}200$ is discounted by $15\\%$. A customer has an additional coupon for $10\\%$ off the already discounted price. What is the final price of the laptop, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '918', ARRAY['918'], E'The first discount reduces the price to $1{,}200 \\times 0.85 = \\$1{,}020$. The additional $10\\%$ coupon reduces this to $1{,}020 \\times 0.90 = \\$918$. A common error is adding the two percentages to get $25\\%$ and computing $1{,}200 \\times 0.75 = \\$900$, which incorrectly treats the discounts as additive rather than successive. Another error is applying the $10\\%$ discount to the original price, yielding $1{,}200 \\times 0.90 \\times 0.85 = \\$918$ — which happens to give the same result here, but misunderstands the order of application.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SV0TIB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A company surveyed $200$ employees about their commute method. Of the $120$ employees who drive, $30$ also use public transit. Of the $60$ employees who use public transit, $30$ also drive. If an employee is selected at random from those who use public transit, what is the probability that this employee also drives?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{30}{200}$"},{"key":"B","text":"$\\frac{30}{120}$"},{"key":"C","text":"$\\frac{30}{60}$"},{"key":"D","text":"$\\frac{60}{200}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The question asks for a conditional probability: given that an employee uses public transit, what is the probability of also driving? There are $60$ employees who use public transit, and $30$ of those also drive, so the conditional probability is $\\frac{30}{60}$, which equals $\\frac{1}{2}$. The distractor $\\frac{30}{200}$ incorrectly uses the total number of employees as the denominator instead of restricting to the public transit group. The distractor $\\frac{30}{120}$ incorrectly conditions on drivers rather than on public transit users. The distractor $\\frac{60}{200}$ gives the probability of using public transit among all employees, ignoring the conditional requirement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SZQ38Q', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 4x - 7$, what is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-16$"},{"key":"B","text":"$0$"},{"key":"C","text":"$5$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $3$ for $x$ gives $f(3) = 4(3) - 7 = 12 - 7 = 5$. The value $19$ results from adding $7$ instead of subtracting it, computing $12 + 7$. The value $-16$ comes from subtracting $7$ from $3$ before multiplying by $4$, computing $4(3 - 7) = 4(-4) = -16$. The value $0$ results from adding $4 + 3 - 7 = 0$ rather than multiplying $4$ by $3$ first.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TRFJYT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'How many distinct real solutions does the system $y = x^2 - 4x + 5$ and $y = 2x - 3$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'C', NULL, E'Set the expressions equal: $x^2 - 4x + 5 = 2x - 3$. Rearranging gives $x^2 - 6x + 8 = 0$. Factor: $(x - 2)(x - 4) = 0$, so $x = 2$ and $x = 4$. Each $x$-value produces a unique $y$-value, yielding $2$ intersection points. The distractor $0$ arises from an error in rearranging the equation (such as obtaining a negative discriminant). The distractor $1$ comes from incorrectly concluding the discriminant is zero. The distractor $4$ reflects a misconception that a quadratic-linear system can produce as many solutions as the sum of the degrees.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2USTR1W', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sold a total of $200$ tickets for a show. Adult tickets cost $\\$12$ each and child tickets cost $\\$8$ each. If the total revenue from ticket sales was $\\$2{,}160$, how many adult tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$60$"},{"key":"C","text":"$120$"},{"key":"D","text":"$140$"}]$lyceon_json$::jsonb, 'D', NULL, E'Let $a$ represent adult tickets and $c$ represent child tickets. The system is $a + c = 200$ and $12a + 8c = 2{,}160$. From the first equation, $c = 200 - a$. Substituting into the second equation: $12a + 8(200 - a) = 2{,}160$, which gives $12a + 1{,}600 - 8a = 2{,}160$, so $4a = 560$ and $a = 140$. The value $40$ results from setting up the revenue equation with swapped coefficients for the ticket prices. The value $60$ is the number of child tickets, not adult tickets. The value $120$ arises from a subtraction error when simplifying $2{,}160 - 1{,}600$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2USVRYS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A chord of a circle is $24$ units long and is $5$ units from the center of the circle. A second chord of the same circle is $10$ units long. What is the distance, in units, from the center of the circle to the second chord?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'First, find the radius. A perpendicular from the center to a chord bisects the chord, so half the first chord is $12$ and the distance from the center is $5$. By the Pythagorean theorem, $r^2 = 12^2 + 5^2 = 144 + 25 = 169$, so $r = 13$. For the second chord of length $10$, half the chord is $5$. Let $d$ be the distance from the center to this chord. Then $d^2 + 5^2 = 13^2$, so $d^2 = 169 - 25 = 144$ and $d = 12$. A common error is forgetting to halve the chord lengths, yielding $r = \\sqrt{576 + 25} = \\sqrt{601}$. Another error is halving the first chord but not the second, computing $d = \\sqrt{169 - 100} = \\sqrt{69}$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VAMN74', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'If $3(2x - 5) \\geq 4x + 7$, what is the least integer value of $x$ that satisfies the inequality?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$11$"},{"key":"C","text":"$12$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing gives $6x - 15 \\geq 4x + 7$. Subtracting $4x$ from both sides yields $2x - 15 \\geq 7$. Adding $15$ to both sides gives $2x \\geq 22$. Dividing both sides by $2$ produces $x \\geq 11$. The least integer satisfying this is $11$. The value $10$ results from a rounding error or off-by-one mistake when identifying the boundary. The value $12$ comes from an arithmetic slip when combining constants. The value $22$ is the intermediate result before dividing by $2$, representing incomplete reasoning.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VSGPJ8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A painter can paint $\\frac{3}{5}$ of a wall in $2$ hours. A second painter can paint $\\frac{1}{4}$ of the same wall in $1$ hour. Working together at their respective constant rates, how many hours will it take both painters to paint the entire wall? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20/11', ARRAY['20/11', '1.818'], E'The first painter''s rate is $\\frac{3/5}{2} = \\frac{3}{10}$ of the wall per hour. The second painter''s rate is $\\frac{1/4}{1} = \\frac{1}{4}$ of the wall per hour. Their combined rate is $\\frac{3}{10} + \\frac{1}{4} = \\frac{6}{20} + \\frac{5}{20} = \\frac{11}{20}$ of the wall per hour. Therefore the time to paint the entire wall is $\\frac{1}{11/20} = \\frac{20}{11}$ hours. A common error is inverting one of the individual rates, and another is adding the times directly rather than adding the rates.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VYANYQ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3(2x - 5) + 4x$?', NULL, $lyceon_json$[{"key":"A","text":"$10x - 15$"},{"key":"B","text":"$10x - 5$"},{"key":"C","text":"$6x - 15$"},{"key":"D","text":"$10x + 15$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $3(2x) - 3(5) + 4x = 6x - 15 + 4x = 10x - 15$. The distractor $10x - 5$ results from failing to multiply $3 \\times 5$ correctly. The distractor $6x - 15$ comes from distributing but neglecting to combine the $4x$ term. The distractor $10x + 15$ arises from a sign error when distributing the $-5$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W6LNTJ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'An electrician charges a $\\$75$ service fee plus $\\$45$ per hour of labor. A plumber charges a $\\$50$ service fee plus $\\$55$ per hour of labor. After how many hours of work will the electrician and the plumber charge the same total amount?', NULL, $lyceon_json$[{"key":"A","text":"$0.25$"},{"key":"B","text":"$2.5$"},{"key":"C","text":"$5$"},{"key":"D","text":"$12.5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the two total charges equal gives $75 + 45h = 50 + 55h$. Subtracting $45h$ and $50$ from both sides yields $25 = 10h$, so $h = 2.5$. The value $0.25$ results from dividing the fee difference by the sum of the hourly rates ($25 \\div 100$) instead of by their difference. The value $5$ comes from dividing only the plumber''s fee by the rate difference ($50 \\div 10$), using an incomplete setup. The value $12.5$ comes from adding the two fees ($125 \\div 10$) rather than subtracting them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XKKO6I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A student scored $72$, $85$, $90$, $68$, and $95$ on five quizzes. What is the median of these scores?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$82$"},{"key":"C","text":"$85$"},{"key":"D","text":"$90$"}]$lyceon_json$::jsonb, 'C', NULL, E'Arranging the scores in order gives $68, 72, 85, 90, 95$. The median is the middle value, which is $85$. The value $72$ results from selecting the second value rather than the third after ordering. The value $82$ is the result of computing the mean instead of the median ($\\frac{68 + 72 + 85 + 90 + 95}{5} = 82$). The value $90$ results from selecting the fourth value in the ordered list instead of the middle one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YJ96LN', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A shipping company charges a flat fee of $\\$8$ plus $\\$0.50$ per pound for standard delivery and a flat fee of $\\$3$ plus $\\$1.25$ per pound for express delivery. For what weight, in pounds, does the standard delivery cost first become less than the express delivery cost? Assume the weight must be a whole number of pounds.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Let $w$ represent the weight in pounds. The standard cost is $8 + 0.50w$ and the express cost is $3 + 1.25w$. Setting up the inequality $8 + 0.50w < 3 + 1.25w$ and subtracting $0.50w$ from both sides gives $8 < 3 + 0.75w$. Subtracting $3$ from both sides yields $5 < 0.75w$. Dividing both sides by $0.75$ gives $w > \\frac{20}{3} \\approx 6.67$. Since the weight must be a whole number of pounds and must exceed $\\frac{20}{3}$, the first whole-number weight where standard delivery is cheaper is $7$ pounds.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YKFHFD', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $\\frac{4x^2 + 12x + 9}{2x + 3} = ax + b$ for all values of $x$ where the expression is defined, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Recognize that the numerator $4x^2 + 12x + 9$ is a perfect square trinomial: $(2x + 3)^2$. Dividing by $(2x + 3)$ gives $\\frac{(2x + 3)^2}{2x + 3} = 2x + 3$. Therefore $a = 2$ and $b = 3$, so $a + b = 5$. A common error is performing polynomial long division incorrectly and obtaining the wrong coefficients. Another error is failing to recognize the perfect square pattern and making arithmetic mistakes when dividing term by term.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW202IM7V', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The common octopus can change its skin color and texture in less than a second. This rapid transformation is controlled by specialized cells called chromatophores, which contain pigment sacs that expand or contract in response to neural signals. <u>Scientists have observed octopuses matching the color and pattern of coral, seaweed, and sandy ocean floors with remarkable accuracy.</u> This camouflage ability helps octopuses avoid predators in diverse marine environments.', $lyceon_json$[{"key":"A","text":"It provides specific examples that illustrate the effectiveness of the ability described earlier in the passage."},{"key":"B","text":"It introduces a new topic unrelated to the chromatophore mechanism discussed in the preceding sentences."},{"key":"C","text":"It presents a counterargument to the claim that octopuses can change color rapidly."},{"key":"D","text":"It defines a technical term that is central to the passage's main argument."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating the sentence provides specific examples illustrating the effectiveness of the ability described earlier. The underlined sentence lists concrete instances — coral, seaweed, and sandy ocean floors — that demonstrate how accurately the octopus can use its chromatophores. The choice claiming a new unrelated topic is introduced is wrong because the examples directly extend the discussion of color-changing ability. The choice proposing a counterargument is wrong because the examples support rather than challenge the claim about rapid color change. The choice about defining a technical term is wrong because the sentence offers observational evidence, not a definition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
