INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23I004V', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Renewable energy sources have expanded rapidly in the past decade. Although solar panel costs have dropped by nearly seventy percent since 2010 ______ many rural communities still lack access to affordable solar installation services.', $lyceon_json$[{"key":"A","text":", many"},{"key":"B","text":"; many"},{"key":"C","text":": many"},{"key":"D","text":"many"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is the one that places a comma after the introductory subordinate clause beginning with ''Although.'' A comma is required to separate a long introductory dependent clause from the independent clause that follows it. The semicolon option is incorrect because a semicolon joins two independent clauses, and a clause beginning with ''Although'' is dependent, not independent. The colon option fails for the same reason: a colon must follow an independent clause. Omitting punctuation entirely creates a confusing run-on in which the dependent clause flows into the independent clause without a necessary pause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW240EN31', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeological evidence from ancient Mesopotamia indicates that early writing systems developed primarily to track commercial transactions such as grain sales and livestock inventories. Some scholars have argued that literary and religious texts emerged only after these practical record-keeping methods were firmly established. _______ recently discovered clay tablets from the site of Tell Brak contain what appear to be mythological narratives alongside accounting records, suggesting that utilitarian and creative uses of writing may have developed concurrently rather than sequentially.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"As a result,"},{"key":"C","text":"That is,"},{"key":"D","text":"Yet"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct transition is "Yet" because the third sentence introduces archaeological evidence that challenges the scholarly argument presented in the second sentence. The tablets from Tell Brak suggest writing had simultaneous practical and creative uses, which contradicts the claim that literary texts came only after record-keeping was established. "In addition" fails to capture this adversative relationship and instead implies the new evidence merely supplements the earlier claim. "As a result" wrongly treats the discovery as a consequence of the scholars'' argument rather than a counterpoint to it. "That is" implies the third sentence restates the second, when it actually undermines it with contrary evidence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24CFDC1', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The city of Vienna became a leading center for classical music composition during the late eighteenth century, attracting composers such as Haydn, Mozart, and Beethoven. _______ the city''s musical reputation did not arise solely from the genius of individual composers; it was also sustained by a network of aristocratic patrons who funded orchestras, commissioned new works, and hosted private concerts in their palaces.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"For instance,"},{"key":"C","text":"However,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "However," because the second sentence qualifies the impression left by the first: while the first sentence attributes Vienna''s musical prominence to famous composers, the second sentence introduces the contrasting point that aristocratic patronage was also essential. "Similarly" incorrectly signals that the second sentence makes a parallel point rather than a qualifying one. "For instance" wrongly treats the discussion of patronage as an example of the composers'' talent. "In other words" implies the second sentence restates the first, but it actually adds a new, contrasting factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24GLVQY', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers studying sleep deprivation have found that even moderate sleep loss impairs cognitive performance, including attention, working memory, and decision-making. These effects are well documented in controlled laboratory settings. _______ field studies of medical residents working extended shifts have produced more ambiguous results: some investigations report significant increases in diagnostic errors, while others find that experienced clinicians compensate for fatigue through established routines and institutional safeguards.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"Accordingly,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "By contrast," because the passage sets up a distinction between two types of evidence: laboratory studies that clearly show cognitive impairment and field studies that yield mixed, ambiguous results. The third sentence contrasts with the certainty described in the second sentence. "Moreover" incorrectly suggests the field studies simply add to the laboratory findings, when they actually complicate them. "Accordingly" implies the field studies follow logically as a consequence of the lab results, but the passage emphasizes that real-world findings do not straightforwardly confirm the lab data. "For example" treats the field studies as an illustration of the lab findings, but the passage characterizes them as yielding different, more ambiguous conclusions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25QCHK7', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In the 1950s, psychologist Solomon Asch conducted experiments demonstrating that individuals frequently conform to group opinion even when the group is clearly wrong. Participants were asked to match line lengths, a task with an obvious correct answer, yet roughly seventy-five percent conformed to an incorrect unanimous group response at least once. Later researchers have debated whether this conformity reflects genuine perceptual change or merely public compliance. Recent neuroimaging studies suggest that social pressure can actually alter perceptual processing in the brain, lending support to the view that conformity is not always a conscious, strategic choice.', $lyceon_json$[{"key":"A","text":"Asch's conformity experiments were methodologically flawed, leading later researchers to revise his conclusions."},{"key":"B","text":"Research on conformity has evolved from behavioral observation to neuroscience, suggesting that social pressure can genuinely affect perception."},{"key":"C","text":"Neuroimaging technology has proven that all instances of conformity result from unconscious perceptual changes rather than deliberate compliance."},{"key":"D","text":"Approximately seventy-five percent of people will conform to a group's opinion regardless of the situation."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the choice stating that conformity research has evolved from behavioral observation to neuroscience, suggesting social pressure can genuinely affect perception. The passage traces a trajectory from Asch''s 1950s behavioral experiments through a debate about the nature of conformity to recent neuroimaging findings that support the idea of genuine perceptual change. The choice about methodological flaws is unsupported: the passage never questions Asch''s methods. The choice claiming that all conformity results from unconscious change overstates the neuroimaging findings, which the passage describes as lending support to one view rather than proving it universally. The choice about seventy-five percent conforming regardless of situation takes a specific experimental statistic and incorrectly generalizes it beyond the controlled conditions Asch used.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26D8AA1', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29E961V', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists studying coral reefs in the Pacific Ocean have documented a sharp decline in reef coverage over the past decade. The researchers attribute this loss primarily to rising ocean temperatures, which cause coral to expel the symbiotic algae living in their tissues. Without these algae, the coral turns white and eventually dies, a process scientists call coral ______.', $lyceon_json$[{"key":"A","text":"bleaching"},{"key":"B","text":"fossilization"},{"key":"C","text":"germination"},{"key":"D","text":"irrigation"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "bleaching." The passage describes coral turning white after expelling algae due to heat stress, which is the process known as coral bleaching. "Fossilization" refers to the process of organic remains becoming preserved in rock over geological timescales, which is unrelated to the living biological process described. "Germination" denotes the sprouting of a seed or spore, a concept from plant biology that has no connection to coral losing algae. "Irrigation" means the artificial supply of water to land for agriculture, which is entirely unrelated to the marine phenomenon described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29FPMME', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The architect Leona Marsh was known for designs that rejected ornamentation in favor of stark geometric forms. Critics who visited her 1963 exhibition noted that even the lighting had been stripped to bare fluorescent tubes, and the gallery walls were left as raw concrete. One reviewer wrote that the exhibition space itself seemed to ______ Marsh''s belief that a building''s structure, unadorned and exposed, constituted its truest aesthetic statement.', $lyceon_json$[{"key":"A","text":"contradict"},{"key":"B","text":"embody"},{"key":"C","text":"obscure"},{"key":"D","text":"inventory"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "embody." The passage describes a gallery space whose raw, unadorned design mirrors Marsh''s architectural philosophy, meaning the space physically incarnates or gives tangible form to her belief. "Contradict" means to assert the opposite of or be inconsistent with, but the passage makes clear that the space aligns with Marsh''s philosophy rather than opposing it. "Obscure" means to make unclear or difficult to perceive, yet the passage indicates the space makes Marsh''s belief visible and apparent, not hidden. "Inventory" means to compile a detailed list or catalog of items, which is nonsensical in the context of a space expressing a philosophical position.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ASX6JC', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Coral reefs occupy less than one percent of the ocean floor, yet they support approximately twenty-five percent of all marine species. This extraordinary biodiversity arises because reefs provide shelter, breeding grounds, and abundant food sources for organisms ranging from microscopic algae to large predatory fish. Scientists often refer to coral reefs as the "rainforests of the sea" to convey the sheer density of life they sustain.', $lyceon_json$[{"key":"A","text":"Coral reefs support a disproportionately large share of marine biodiversity relative to the area they occupy."},{"key":"B","text":"Scientists have recently discovered that coral reefs are more important than rainforests for global biodiversity."},{"key":"C","text":"Microscopic algae are the most critical organisms living within coral reef ecosystems."},{"key":"D","text":"Coral reefs are rapidly declining due to environmental threats such as ocean warming."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that coral reefs support a disproportionately large share of marine biodiversity relative to their area. The passage opens by contrasting the small area reefs occupy (less than one percent of the ocean floor) with the large proportion of species they support (approximately twenty-five percent), making this disproportion the central point. The choice claiming reefs are more important than rainforests misreads the analogy: the passage compares reefs to rainforests to illustrate biodiversity density, not to rank their importance. The choice about microscopic algae elevates one detail from a list of organisms without reflecting the passage''s broader point. The choice about reef decline introduces a topic the passage never discusses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B0NS1V', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall purpose of the text?', E'When the playwright Anika Soren adapted a nineteenth-century novel into a stage production in 2019, critics were divided. Some praised her decision to reorder the novel''s chapters, arguing that the nonlinear structure heightened dramatic tension. Others contended that the rearrangement sacrificed the novel''s carefully constructed thematic progression, leaving audiences unable to track the protagonist''s moral development. Soren herself maintained that fidelity to a source text''s sequence is less important than capturing what she called its "emotional architecture" — the pattern of feelings a reader experiences, which she argued could be recreated through entirely different narrative means.', $lyceon_json$[{"key":"A","text":"To argue that stage adaptations of novels should always preserve the original narrative sequence."},{"key":"B","text":"To present differing critical reactions to an adaptation and the adapter's rationale for her artistic choices."},{"key":"C","text":"To demonstrate that nonlinear storytelling is inherently superior to chronological narrative in theatrical productions."},{"key":"D","text":"To chronicle the historical relationship between nineteenth-century novels and modern theater."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the choice stating the text presents differing critical reactions and the adapter''s rationale. The passage lays out two contrasting critical views — praise for heightened tension versus concern about lost thematic progression — and then presents Soren''s own justification centered on "emotional architecture." The choice claiming the text argues for preserving narrative sequence is wrong because the passage presents multiple viewpoints without endorsing any single position. The choice asserting nonlinear storytelling is shown to be inherently superior is wrong because the text includes criticism of the nonlinear approach and does not declare it superior. The choice about chronicling a historical relationship is wrong because the passage focuses on a single adaptation and its reception, not on a broad historical survey.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DC7WMP', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In her 1951 study of organizational behavior, sociologist Meredith Calloway argued that corporate hierarchies often discourage dissent among employees. According to Calloway, workers who raise objections to managerial decisions are frequently marginalized, which creates a culture of ______ in which employees withhold criticism even when they recognize significant flaws in company strategy.', $lyceon_json$[{"key":"A","text":"innovation"},{"key":"B","text":"acquiescence"},{"key":"C","text":"belligerence"},{"key":"D","text":"transparency"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "acquiescence." The passage describes employees who withhold criticism and suppress objections, which is the definition of acquiescence — passive acceptance without protest. "Innovation" denotes the introduction of new methods or ideas, which contradicts the passage''s description of a culture that suppresses new input. "Belligerence" means hostile aggression or eagerness to fight, the opposite of the passive compliance described. "Transparency" refers to openness and visibility in operations, which contradicts the concealment of criticism the passage describes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FQ7U2X', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The committee overseeing the city''s historic preservation efforts recently reviewed a proposal to renovate the abandoned Monarch Theater. In its report, the committee recommended that the building ______ restored to reflect its original 1920s architectural style rather than modernized to meet current commercial standards.', $lyceon_json$[{"key":"A","text":"is"},{"key":"B","text":"was"},{"key":"C","text":"be"},{"key":"D","text":"would be"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses the subjunctive form ''be.'' In Standard English, verbs of recommendation, demand, and suggestion (such as ''recommended that'') require the subjunctive mood in the clause that follows. The subjunctive uses the base form of the verb regardless of the subject''s person or number, so ''the building be restored'' is correct. The indicative ''is'' does not conform to the subjunctive construction required after ''recommended that.'' The past-tense ''was'' similarly fails to satisfy the subjunctive requirement. The conditional ''would be'' introduces a hypothetical framing that is not called for by the construction; the subjunctive directly expresses the substance of the recommendation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GIEVIZ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing about advances in battery technology for an engineering journal, a student wants to acknowledge a limitation of solid-state batteries while emphasizing their overall promise for electric vehicle applications. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HX59EZ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The growing popularity of electric vehicles has prompted several countries to invest in charging infrastructure. A network of fast-charging stations along the nation''s major ______ it possible for drivers to travel long distances without worrying about running out of battery power.', $lyceon_json$[{"key":"A","text":"highways makes"},{"key":"B","text":"highways make"},{"key":"C","text":"highways making"},{"key":"D","text":"highways have made"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses the singular verb ''makes'' to agree with the singular subject ''A network.'' Although the intervening prepositional phrases ''of fast-charging stations'' and ''along the nation''s major highways'' contain plural nouns, they do not change the number of the subject. The plural verb ''make'' incorrectly treats a nearby plural noun as the subject. The participle ''making'' produces a sentence fragment because it does not function as a finite verb. The plural past-tense form ''have made'' also fails to agree with the singular subject ''A network.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IAB3V7', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ecologist Maria Torres spent five years tracking the migration patterns of monarch butterflies across North America. Neither the severe drought that struck the southern breeding grounds in 2023 nor the unusually cold spring that delayed the butterflies'' northward journey ______ enough to prevent the population from reaching its historical nesting sites in central Mexico.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"being"},{"key":"C","text":"have been"},{"key":"D","text":"was"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct choice uses the singular verb ''was.'' With the correlative conjunction ''neither...nor,'' the verb agrees in number with the subject closer to it. The nearer subject is ''the unusually cold spring that delayed the butterflies'' northward journey,'' which is singular, so the singular ''was'' is required. The plural ''were'' incorrectly treats the compound subject as plural; although two elements are named, ''neither...nor'' negates each one individually and requires agreement with the nearer element. The participle ''being'' does not function as a finite verb and produces a sentence fragment. The plural ''have been'' commits the same agreement error as ''were'' while also shifting to the present perfect tense, which conflicts with the past-tense narrative established by ''spent.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KAS8LX', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing an article about urban farming, a student wants to emphasize the economic benefits of rooftop gardens for building owners. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LRG71C', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Astronomers have long known that Mercury, the planet closest to the Sun, has virtually no atmosphere. Without a substantial atmosphere to distribute heat, the planet''s surface temperature swings wildly: the side facing the Sun can reach 430 degrees Celsius, while the side facing away can plummet to negative 180 degrees Celsius. This extreme variation means that, despite Mercury''s proximity to the Sun, ________', $lyceon_json$[{"key":"A","text":"Mercury is not uniformly hot across its entire surface."},{"key":"B","text":"Mercury is the hottest planet in the solar system at all points on its surface."},{"key":"C","text":"Mercury's atmosphere is primarily composed of helium and hydrogen."},{"key":"D","text":"Mercury orbits the Sun more slowly than any other inner planet."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the statement that Mercury is not uniformly hot across its entire surface. The passage establishes that Mercury lacks an atmosphere to distribute heat, resulting in extreme temperature differences between its sun-facing and opposite sides. The logical conclusion is that proximity to the Sun does not make Mercury uniformly hot. The claim that Mercury is the hottest planet at all surface points contradicts the passage''s own data showing the dark side reaches negative 180 degrees Celsius. The claim about atmospheric composition introduces information the passage does not discuss and contradicts the statement that Mercury has virtually no atmosphere. The claim about orbital speed is unrelated to the passage''s discussion of temperature variation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MBJHYC', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The discovery of high concentrations of methane in the Martian atmosphere has puzzled planetary scientists for years. The Curiosity ______ which has been exploring Gale Crater since 2012, detected seasonal spikes in methane that cannot be explained by known geological processes.', $lyceon_json$[{"key":"A","text":"rover"},{"key":"B","text":"rover;"},{"key":"C","text":"rover,"},{"key":"D","text":"rover:"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice places a comma after ''rover'' to open the nonrestrictive clause ''which has been exploring Gale Crater since 2012.'' Since ''The Curiosity rover'' already identifies a specific rover, the ''which'' clause provides additional, nonessential information and must be set off by commas on both sides. Omitting the comma before ''which'' fails to signal that the clause is nonrestrictive, creating ambiguity about whether the clause is meant to restrict the noun. A semicolon cannot precede a relative clause because the clause is not an independent sentence. A colon is similarly inappropriate before a relative pronoun introducing a modifying clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N6AG2I', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Jazz pianist Thelonious Monk was known for his unconventional approach to harmony and rhythm. His compositions, characterized by dissonant chords and abrupt ______ have since become standards in the jazz repertoire, performed by musicians around the world.', $lyceon_json$[{"key":"A","text":"pauses;"},{"key":"B","text":"pauses"},{"key":"C","text":"pauses."},{"key":"D","text":"pauses,"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct choice places a comma after ''pauses'' to close the participial phrase ''characterized by dissonant chords and abrupt pauses.'' The subject of the sentence is ''His compositions,'' and its main verb is ''have since become.'' The participial phrase between them is a parenthetical modifier that was opened with a comma after ''compositions'' and must be closed with a matching comma after ''pauses.'' A semicolon after ''pauses'' would incorrectly split the sentence, orphaning ''have since become'' from its subject. Omitting punctuation entirely leaves the participial phrase without a closing boundary, causing readers to misparse ''abrupt pauses have since become'' as a single clause. A period after ''pauses'' creates a sentence fragment (''His compositions, characterized by dissonant chords and abrupt pauses.'') and leaves the following clause without a subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NW85R6', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes a point of disagreement between the author of Text 1 and the author of Text 2?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NWGAR3', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the nineteenth century, many European museums acquired artifacts from ancient civilizations through colonial expeditions and unregulated markets. In recent decades, countries of origin have increasingly demanded the return of these objects, arguing that they were removed without consent and hold irreplaceable cultural significance. Some museums have complied, returning high-profile pieces amid public ceremonies, while others have resisted, citing legal acquisition records and the argument that global collections promote cross-cultural understanding. The ongoing disputes suggest that ________', $lyceon_json$[{"key":"A","text":"the question of who rightfully owns cultural artifacts involves competing claims that current legal frameworks have not fully resolved."},{"key":"B","text":"all European museums will eventually return every artifact acquired during the colonial period to the countries of origin."},{"key":"C","text":"museums that resist repatriation do so primarily because the artifacts are too fragile to transport safely."},{"key":"D","text":"countries of origin have lost interest in pursuing repatriation because the legal process is prohibitively expensive."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the statement that ownership of cultural artifacts involves competing claims that current legal frameworks have not fully resolved. The passage presents two sides—countries demanding return and museums citing legal records and educational value—and describes the disputes as ongoing, implying unresolved tension rather than a settled outcome. The prediction that all museums will eventually return every artifact goes far beyond what the passage supports; it describes partial compliance, not a universal trajectory. The claim about fragility as the reason for resistance introduces a factor the passage never mentions; the cited reasons are legal records and cross-cultural understanding. The claim that countries have lost interest directly contradicts the passage''s statement that demands for return have been increasing in recent decades.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NWXJZ8', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A researcher hypothesizes that urban noise pollution impairs songbirds'' ability to communicate effectively. Which finding, if true, would most directly support this hypothesis?', E'Songbirds in urban environments face acoustic challenges absent from rural habitats. Traffic, construction, and industrial machinery generate persistent low-frequency noise that overlaps with the frequency range many songbird species use for territorial calls and mating songs. Field studies in several European cities have recorded shifts in the vocal behavior of urban bird populations compared with their rural counterparts. Some researchers have proposed that these behavioral changes may carry reproductive consequences if modified songs are less effective at attracting mates or defending territories.', $lyceon_json$[{"key":"A","text":"Urban songbirds that shifted their call frequencies to avoid traffic noise experienced lower mate-attraction success than rural birds using unmodified calls."},{"key":"B","text":"Songbird populations in urban areas have declined over the past two decades due to habitat loss and predation by domestic cats."},{"key":"C","text":"Rural songbirds exposed to recorded traffic noise in a laboratory showed elevated stress hormone levels compared with a control group."},{"key":"D","text":"Some urban songbird species have adapted to city environments by nesting on building ledges and foraging from human food waste."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the finding that urban songbirds shifting call frequencies experienced lower mate-attraction success. This directly links noise-induced vocal changes to impaired communication effectiveness, which is the specific claim the hypothesis makes. The finding about population decline from habitat loss and cat predation addresses different causes of decline, not communication impairment from noise. The finding about elevated stress hormones demonstrates a physiological response to noise but does not show that communication itself was impaired. The finding about nesting and foraging adaptations describes behavioral flexibility unrelated to vocal communication.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O5LIGO', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the University of Tokyo have developed a biodegradable plastic derived entirely from plant starch. Unlike conventional plastics, which can persist in landfills for hundreds of ______ the new material breaks down within three months when exposed to moisture and microorganisms in soil.', $lyceon_json$[{"key":"A","text":"years;"},{"key":"B","text":"years,"},{"key":"C","text":"years:"},{"key":"D","text":"years"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice places a comma after ''years'' to close the nonrestrictive clause ''which can persist in landfills for hundreds of years.'' The main clause begins with ''Unlike conventional plastics'' and continues with ''the new material breaks down,'' so the ''which'' clause is a parenthetical interruption that must be enclosed by commas on both sides. A semicolon would incorrectly break the sentence at the boundary of the nonrestrictive clause, severing ''the new material breaks down'' from the comparison structure that begins with ''Unlike.'' A colon commits the same error, treating what follows as an independent elaboration rather than the continuation of the main clause. Omitting punctuation entirely removes the closing boundary of the parenthetical, making the sentence difficult to parse and leaving the nonrestrictive clause improperly punctuated.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OIJT16', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, historians characterized the decline of the Roman Republic as a consequence of military overextension and economic strain. More recent scholarship, however, has shifted attention to the role of political institutions. Historian Clara Voss, for example, has argued that the Republic''s collapse was driven not by external pressures but by internal failures: the Senate''s inability to adapt its constitutional framework to govern an expanding empire made authoritarian consolidation of power nearly inevitable.', $lyceon_json$[{"key":"A","text":"It presents a traditional explanation and then introduces a contrasting scholarly perspective that challenges it."},{"key":"B","text":"It describes two competing military strategies and evaluates which was more effective."},{"key":"C","text":"It summarizes a historian's findings and then raises methodological objections to her approach."},{"key":"D","text":"It traces the chronological stages of a political transformation from republic to empire."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the text presents a traditional explanation and then introduces a contrasting scholarly perspective. The passage first describes the older view (military overextension and economic strain) and then pivots with "however" to present Voss''s institutional argument. The choice about competing military strategies is wrong because the passage does not compare strategies; it contrasts explanatory frameworks for the Republic''s decline. The choice about methodological objections is wrong because the passage presents Voss''s argument favorably, with no critique of her methods. The choice about chronological stages is wrong because the passage compares interpretive frameworks rather than narrating a sequence of historical events.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PDVCG5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Although the green revolution of the 1960s dramatically increased crop yields through high-yield seed varieties, synthetic fertilizers, and irrigation expansion, its long-term ecological costs have prompted a reassessment. Soil degradation, aquifer depletion, and biodiversity loss now threaten the very agricultural productivity the revolution was designed to secure. Some agronomists advocate a return to traditional polyculture and agroforestry methods, arguing that these systems maintain soil health and ecological balance. Others counter that feeding a global population projected to exceed nine billion by 2050 requires further technological innovation, not a retreat to lower-yield practices. The debate, then, is not simply about farming methods but about how societies weigh immediate food security against long-term environmental sustainability.', $lyceon_json$[{"key":"A","text":"The ecological damage caused by green-revolution farming practices has led to a broader debate about balancing food security with environmental sustainability."},{"key":"B","text":"Traditional polyculture and agroforestry methods are more effective than green-revolution techniques at maintaining long-term agricultural productivity."},{"key":"C","text":"The green revolution failed to achieve its primary goal of increasing global crop yields during the 1960s."},{"key":"D","text":"Technological innovation in agriculture is unnecessary because soil degradation and biodiversity loss can be reversed through existing farming practices."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage''s central idea is that the ecological costs of green-revolution farming have sparked a debate between those favoring traditional methods and those advocating further innovation, and that this disagreement ultimately concerns the tradeoff between immediate food security and long-term sustainability. The choice stating that traditional methods are more effective than green-revolution techniques takes one side of the debate the passage presents neutrally, overstating what the text supports. The choice claiming the green revolution failed to increase yields directly contradicts the passage''s opening statement that it dramatically increased crop yields. The choice asserting that technological innovation is unnecessary because existing practices can reverse damage misrepresents both sides: the passage does not claim that damage is easily reversible, and it presents the pro-innovation position as a serious counterargument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V90ALZ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A student claims that leafcutter ants rely on a division of labor to sustain their colonies. Which finding from the text, if true, would most directly support this claim?', E'Leafcutter ant colonies can contain millions of individuals organized into distinct castes. Large workers, called majors, defend the colony from intruders. Medium-sized workers, known as mediae, cut and transport leaf fragments back to the nest. The smallest workers, or minors, tend fungal gardens inside the colony, cultivating the fungus that serves as the colony''s primary food source. Each caste performs its tasks consistently, and researchers have observed that removing one caste severely disrupts the colony''s functioning.', $lyceon_json$[{"key":"A","text":"Removing one caste disrupts colony functioning because no other caste takes over the missing group's tasks."},{"key":"B","text":"Leafcutter ant colonies can grow to contain several million individuals."},{"key":"C","text":"Leafcutter ants are found primarily in tropical and subtropical regions of the Americas."},{"key":"D","text":"The fungus cultivated by leafcutter ants also grows naturally in certain forest environments."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the finding that removing one caste disrupts colony functioning because no other caste assumes the missing group''s tasks. This directly demonstrates reliance on a division of labor: if each caste''s role were interchangeable, removal would not cause disruption. The finding about colony population size speaks to scale, not to how labor is organized. The finding about geographic range concerns habitat distribution, which is unrelated to labor division. The finding about fungus growing naturally in forests addresses the fungus''s biology rather than how ant labor sustains the colony.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VZ50KY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing a research summary for a general audience, a student wants to present a contrast between traditional assumptions about octopus behavior and recent scientific findings. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WKA294', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Philosopher Martha Nussbaum has argued that literary reading cultivates moral imagination by requiring readers to inhabit perspectives radically different from their own. Empirical psychologists have tested this claim by measuring empathy levels in participants before and after reading literary fiction versus nonfiction. Some studies found a small but statistically significant increase in empathy scores among fiction readers, while others failed to replicate the effect. Critics of these experiments note that empathy is a multidimensional construct difficult to capture with self-report questionnaires, and that a single reading session may be too brief to produce measurable change. Taken together, these considerations suggest that ________', $lyceon_json$[{"key":"A","text":"while there is theoretical reason to believe literary reading enhances empathy, the empirical evidence remains inconclusive partly because of methodological limitations in how empathy is measured and how reading interventions are designed."},{"key":"B","text":"Nussbaum's philosophical argument has been conclusively disproven by the failure of several empirical studies to demonstrate a link between literary reading and empathy."},{"key":"C","text":"self-report questionnaires are the most reliable instruments available for measuring empathy, despite some critics' objections to their use."},{"key":"D","text":"reading nonfiction is at least as effective as reading literary fiction in cultivating empathy, since the empirical studies found no consistent difference between the two."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the statement that theoretical reasons support the reading-empathy link but empirical evidence remains inconclusive partly due to methodological limitations. The passage presents Nussbaum''s theoretical claim, describes mixed empirical results, and cites methodological critiques—measurement difficulty and intervention brevity—that could account for inconsistent findings. This completion synthesizes all three elements without overstating any. The claim that Nussbaum''s argument has been conclusively disproven misrepresents the mixed evidence: some studies did find a significant effect, and critics question the methods rather than declaring the hypothesis false. The claim that self-report questionnaires are the most reliable instruments reverses the passage''s point; critics cite their limitations as a reason results may be unreliable. The claim that nonfiction is equally effective misreads the mixed results: failure to consistently replicate a fiction advantage is not evidence that nonfiction produces equivalent empathy gains, especially given the noted methodological concerns.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WLKI3M', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Archaeological evidence suggests that the ancient Indus Valley civilization had a sophisticated system of urban planning. Excavations at the site of Mohenjo-daro, which began in the 1920s, ______ that the city''s streets were laid out in a precise grid pattern, with advanced drainage systems running beneath them.', $lyceon_json$[{"key":"A","text":"has revealed"},{"key":"B","text":"have revealed"},{"key":"C","text":"revealing"},{"key":"D","text":"had revealed"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses ''have revealed,'' which agrees in number with the plural subject ''Excavations.'' The nonrestrictive clause ''which began in the 1920s'' intervenes between the subject and the verb, but it does not change the number of the subject. The singular ''has revealed'' incorrectly treats a nearby singular noun such as ''site'' or ''Mohenjo-daro'' as the subject. The participle ''revealing'' fails to provide a finite verb for the main clause, producing a fragment. The past perfect ''had revealed'' requires a clear subsequent past-tense event as a reference point, which the sentence does not establish; the present perfect correctly conveys that the excavations, which began in the past, have produced findings relevant to the present.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WU8R0N', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists have long known that coral reefs support an extraordinary variety of fish species. _______ a 2024 survey of the Great Barrier Reef documented over 1,500 distinct species inhabiting a single reef system, confirming the exceptional biodiversity of these ecosystems.', $lyceon_json$[{"key":"A","text":"In fact,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "In fact," because the second sentence provides specific evidence that reinforces and intensifies the claim made in the first sentence about coral reefs supporting extraordinary biodiversity. "Nevertheless" and "In contrast" incorrectly signal a contradiction between the two sentences, when the second sentence actually supports the first. "Consequently" wrongly implies that the survey was a result of biologists'' knowledge, rather than a piece of confirming evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YI17P8', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A literary scholar argues that the narrator''s description of the garden reveals an underlying anxiety about the passage of time rather than a straightforward appreciation of nature. Which quotation from the text would most directly support the scholar''s interpretation?', E'The garden in late summer was almost overwhelming in its abundance. Roses crowded the iron fence, their petals darkening at the edges as though singed by some invisible flame. The tomato vines had outgrown their stakes and sprawled across the walkway in tangled heaps. Mrs. Harlow moved through the rows slowly, pausing to deadhead spent blooms, though she knew the effort was futile now. The season had already crested. In two weeks, the first frost advisory would come, and everything she had tended since April would collapse into brown. She pressed a ripe tomato between her fingers, feeling its warmth, and set it in the basket with a care that surprised even herself.', $lyceon_json$[{"key":"A","text":"\"Roses crowded the iron fence, their petals darkening at the edges as though singed by some invisible flame.\""},{"key":"B","text":"\"The tomato vines had outgrown their stakes and sprawled across the walkway in tangled heaps.\""},{"key":"C","text":"\"She pressed a ripe tomato between her fingers, feeling its warmth, and set it in the basket with a care that surprised even herself.\""},{"key":"D","text":"\"In two weeks, the first frost advisory would come, and everything she had tended since April would collapse into brown.\""}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is the quotation about the frost advisory and everything collapsing into brown. This sentence most directly reveals anxiety about time''s passage: the narrator anticipates imminent destruction of months of labor, framing the garden''s future in terms of loss and inevitability. The quotation about petals darkening as though singed hints at decay through imagery but does not explicitly connect the image to the passage of time or anxiety about it, making it suggestive rather than direct support. The quotation about tomato vines sprawling describes overgrowth, which could indicate abundance rather than temporal anxiety. The quotation about pressing the tomato with surprising care suggests emotional attachment but does not articulate anxiety about time; it could equally reflect simple appreciation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
